css:
/* Y3K · 复古未来主义
   2000 年代怀旧 + 科幻想象：铬金属、宇宙霓虹、宽字标与舷窗式面板。
   深空底座上叠银蓝/紫铬渐变，标题像镀了一层金属。纯 CSS。 */

html[data-theme] {
  color-scheme: dark;
  --bg: #06040f;
  --ink: #ece9ff; --muted: #a5a3c4; --dim: #76749a;
  --soft: #cfcbf0; --meta: #a5a3c4; --bright: #ffffff;
  --line: rgba(176, 107, 255, 0.24); --line2: rgba(120, 200, 255, 0.12);
  --accent: #b06bff; --accent2: #6fe4ff; --accentText: #0a0618;
  --good: #74f0c8; --warn: #ffd166;
  --glow1: rgba(176, 107, 255, 0.26); --glow2: rgba(111, 228, 255, 0.22);
  --panel: rgba(20, 16, 40, 0.72); --panel2: rgba(28, 22, 54, 0.82);
  --dock1: rgba(24, 18, 46, 0.86); --dock2: rgba(10, 8, 24, 0.94);
  --glass: rgba(16, 12, 32, 0.8);
  --track: rgba(176, 107, 255, 0.16); --scroll: rgba(176, 107, 255, 0.4); --coverbg: #120e28;
  --menu: rgba(14, 11, 30, 0.96); --menu1: rgba(22, 17, 44, 0.96); --menu2: rgba(8, 6, 18, 0.98); --chev: #8e86b8;
  --edge: rgba(176, 107, 255, 0.4); --edge2: rgba(111, 228, 255, 0.4);
  --hover: rgba(176, 107, 255, 0.1); --tick: rgba(176, 107, 255, 0.3);
  --inset: rgba(255, 255, 255, 0.24); --wordactive: #ffffff; --swborder: rgba(176, 107, 255, 0.55);
  --shadow-dock: 0 0 0 1px rgba(176, 107, 255, 0.45), 0 30px 80px -34px rgba(176, 107, 255, 0.4);
  --serif: "Michroma", "Bahnschrift", "Segoe UI Variable Display", "PingFang SC", sans-serif;
  --sans: "Bahnschrift", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;
  --bottom: 138px;
  --shell-nav: rgba(14, 10, 30, 0.9); --shell-nav2: rgba(14, 10, 30, 0.9);
  --shell-navin: #ece9ff; --shell-navmuted: #a5a3c4; --shell-navline: rgba(176, 107, 255, 0.3);
}

html[data-theme] body {
  background:
    radial-gradient(900px 620px at 12% -10%, rgba(176, 107, 255, 0.34), transparent 62%),
    radial-gradient(820px 560px at 92% 2%, rgba(111, 228, 255, 0.24), transparent 66%),
    radial-gradient(700px 480px at 62% 108%, rgba(255, 106, 61, 0.16), transparent 64%),
    radial-gradient(2px 2px at 20% 30%, rgba(255, 255, 255, 0.7), transparent 60%),
    radial-gradient(2px 2px at 72% 18%, rgba(255, 255, 255, 0.5), transparent 60%),
    radial-gradient(1.5px 1.5px at 40% 72%, rgba(255, 255, 255, 0.45), transparent 60%),
    #06040f;
}
html[data-theme] body::after {
  content: ""; position: fixed; inset: 0; pointer-events: none; z-index: 1; opacity: 0.4;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='2'/><feColorMatrix type='saturate' values='0'/></filter><rect width='100%25' height='100%25' filter='url(%23n)' opacity='0.22'/></svg>");
  mix-blend-mode: soft-light;
}

/* 侧栏：舷窗金属板 */
html[data-theme] .sidebar {
  margin: 14px 0 14px 14px; padding: 24px 14px;
  border: 1px solid rgba(176, 107, 255, 0.45); border-radius: 22px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.12), transparent 32%),
    linear-gradient(180deg, rgba(26, 20, 52, 0.92), rgba(8, 6, 18, 0.96));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3), 0 0 44px -20px rgba(176, 107, 255, 0.55);
}
html[data-theme] .brand { padding: 2px 8px 22px; border-bottom: 1px solid rgba(176, 107, 255, 0.3); margin-bottom: 16px; }
html[data-theme] .brand .brand-name, html[data-theme] .brand strong {
  font-family: var(--serif); letter-spacing: 0.18em; text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff, #cfd8ff 40%, #b06bff 78%, #6fe4ff);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
html[data-theme] .nav button {
  border: 1px solid transparent; border-radius: 12px; font-family: var(--sans);
  font-size: 11.5px; letter-spacing: 0.1em; text-transform: uppercase; color: #a5a3c4;
}
html[data-theme] .nav button:hover { color: #ece9ff; border-color: rgba(111, 228, 255, 0.35); background: rgba(111, 228, 255, 0.06); }
html[data-theme] .nav button.active {
  color: #0a0618; font-weight: 700;
  background: linear-gradient(96deg, #cfd8ff, #b06bff 58%, #6fe4ff);
  box-shadow: 0 0 26px -6px rgba(176, 107, 255, 0.6);
}

/* 顶栏：仪表条 */
html[data-theme] .topbar {
  margin-top: 14px; padding: 0 18px; height: 62px; border: 1px solid rgba(176, 107, 255, 0.35); border-radius: 18px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.1), transparent 48%),
    rgba(12, 9, 26, 0.86);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.25), 0 0 34px -22px rgba(176, 107, 255, 0.6);
  backdrop-filter: blur(22px); -webkit-backdrop-filter: blur(22px);
}
html[data-theme] .search-global { border: 1px solid rgba(111, 228, 255, 0.3); border-radius: 999px; background: rgba(111, 228, 255, 0.06); }
html[data-theme] .icon-btn { border: 1px solid rgba(176, 107, 255, 0.35); border-radius: 999px; background: rgba(255, 255, 255, 0.06); }

/* 首页：金属字标 */
html[data-theme] .ledger-mast {
  margin-top: 22px; padding: 34px 32px; border: 1px solid rgba(176, 107, 255, 0.4); border-radius: 26px;
  background:
    radial-gradient(560px 300px at 88% -16%, rgba(111, 228, 255, 0.26), transparent 64%),
    linear-gradient(150deg, rgba(255, 255, 255, 0.12), transparent 38%),
    linear-gradient(180deg, rgba(24, 18, 48, 0.9), rgba(8, 6, 18, 0.92));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.32), 0 34px 80px -50px rgba(176, 107, 255, 0.6);
}
html[data-theme] .ledger-mast h1, html[data-theme] .ledger-mast .mast-title {
  font-family: var(--serif); font-size: clamp(38px, 5.2vw, 72px); line-height: 1.02; letter-spacing: 0.04em;
  text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff 0%, #cfd8ff 26%, #8f9fd6 44%, #ffffff 56%, #b06bff 78%, #6fe4ff 100%);
  -webkit-background-clip: text; background-clip: text;
  -webkit-text-fill-color: transparent; color: transparent;
  filter: drop-shadow(0 2px 10px rgba(176, 107, 255, 0.35));
}
html[data-theme] .ledger-mast h1 em { background: linear-gradient(96deg, #6fe4ff, #b06bff); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; }
html[data-theme] .ledger-mast p, html[data-theme] .subtitle { color: #a5a3c4; }

/* 卡片：铬边玻璃 */
html[data-theme] .card, html[data-theme] .pod-card, html[data-theme] .continue {
  border: 1px solid rgba(176, 107, 255, 0.32); border-radius: 20px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.1), transparent 40%),
    linear-gradient(180deg, rgba(24, 18, 48, 0.74), rgba(10, 8, 24, 0.86));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.22);
  backdrop-filter: none; -webkit-backdrop-filter: none;
}
html[data-theme] .pod-card:hover, html[data-theme] .continue:hover {
  border-color: rgba(111, 228, 255, 0.6); transform: translateY(-3px);
  box-shadow: 0 0 34px -14px rgba(111, 228, 255, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.3);
}
html[data-theme] .btn {
  border: 1px solid rgba(176, 107, 255, 0.45); border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.14), rgba(255, 255, 255, 0.04));
  color: #ece9ff; font-size: 10.5px; letter-spacing: 0.1em; text-transform: uppercase;
}
html[data-theme] .btn.primary { background: linear-gradient(96deg, #cfd8ff, #b06bff 58%, #6fe4ff); color: #0a0618; border: 0; }

/* 统计 */
html[data-theme] #page-stats .page-head {
  margin: 18px 0; padding: 30px 32px; border: 1px solid rgba(176, 107, 255, 0.4); border-radius: 26px;
  background:
    radial-gradient(560px 300px at 84% -18%, rgba(176, 107, 255, 0.3), transparent 64%),
    linear-gradient(180deg, rgba(22, 16, 44, 0.9), rgba(8, 6, 18, 0.92));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.28);
}
html[data-theme] #page-stats .page-head h1 {
  font-family: var(--serif); font-size: clamp(30px, 4.4vw, 54px); letter-spacing: 0.04em; text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff, #cfd8ff 34%, #b06bff 70%, #6fe4ff);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent;
}
html[data-theme] #page-stats .eyebrow { color: #6fe4ff; letter-spacing: 0.28em; }
html[data-theme] #page-stats .stat {
  border: 1px solid rgba(176, 107, 255, 0.36); border-radius: 20px; padding: 20px 22px;
  background:
    linear-gradient(160deg, rgba(255, 255, 255, 0.1), transparent 44%),
    linear-gradient(180deg, rgba(24, 18, 48, 0.8), rgba(10, 8, 24, 0.9));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.26);
  position: relative; overflow: hidden;
}
html[data-theme] #page-stats .stat:before { content: ""; background: linear-gradient(180deg, #b06bff, #6fe4ff); width: 2px; opacity: 1; }
html[data-theme] #page-stats .stat label { color: #a5a3c4; letter-spacing: 0.16em; }
html[data-theme] #page-stats .stat strong {
  font-family: var(--serif); font-size: 32px; letter-spacing: 0.02em;
  background: linear-gradient(96deg, #ffffff, #cfd8ff 46%, #6fe4ff);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent;
}
html[data-theme] #page-stats .stat em { color: #76749a; }
html[data-theme] #page-stats .card { border-radius: 20px; padding: 22px; }
html[data-theme] #page-stats .section-title { font-family: var(--serif); font-size: 12px; letter-spacing: 0.12em; text-transform: uppercase; border-bottom: 1px solid rgba(176, 107, 255, 0.22); }
html[data-theme] #page-stats .stat-bar { border-radius: 10px; background: rgba(255, 255, 255, 0.04); }
html[data-theme] #page-stats .stat-track { height: 6px; border-radius: 999px; background: rgba(176, 107, 255, 0.14); box-shadow: none; }
html[data-theme] #page-stats .stat-track i { border-radius: 999px; background: linear-gradient(90deg, #b06bff, #6fe4ff); box-shadow: 0 0 14px rgba(176, 107, 255, 0.6); }
html[data-theme] #page-stats .stats-year-head {
  margin-top: 30px; padding: 28px 32px; border: 1px solid rgba(111, 228, 255, 0.34); border-radius: 26px;
  background:
    radial-gradient(560px 300px at 80% -20%, rgba(111, 228, 255, 0.26), transparent 64%),
    linear-gradient(180deg, rgba(18, 16, 40, 0.9), rgba(8, 6, 18, 0.92));
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.24);
}
html[data-theme] #page-stats .year-title {
  font-family: var(--serif); font-size: 44px; letter-spacing: 0.05em; text-transform: uppercase;
  background: linear-gradient(96deg, #ffffff, #6fe4ff 44%, #b06bff);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; color: transparent;
}
html[data-theme] #page-stats #echoYear { border: 1px solid rgba(176, 107, 255, 0.45); border-radius: 999px; background: rgba(176, 107, 255, 0.12); color: #ece9ff; font-size: 11px; }
html[data-theme] #page-stats #echoBody { padding: 22px; }

/* 设置 */
html[data-theme] .ct-box { border: 1px solid rgba(176, 107, 255, 0.34); border-radius: 18px; background: rgba(16, 12, 32, 0.72); }
html[data-theme] .ct-code, html[data-theme] #ctCss, html[data-theme] #ctHtml {
  border: 1px solid rgba(111, 228, 255, 0.26); border-radius: 12px; background: rgba(6, 5, 14, 0.8); color: #cfd8ff;
}

/* 播放舱：铬壳 */
@media (min-width: 901px) {
  html[data-theme] body .dock {
    left: 50%; right: auto; bottom: 18px; translate: -50% 0;
    width: min(880px, calc(100vw - 40px)); max-width: calc(100vw - 24px);
    padding: 14px 24px 16px; border: 1px solid rgba(176, 107, 255, 0.45); border-radius: 26px;
    background:
      linear-gradient(170deg, rgba(255, 255, 255, 0.12), transparent 44%),
      linear-gradient(180deg, rgba(26, 20, 52, 0.9), rgba(8, 6, 18, 0.94));
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.3), 0 0 44px -22px rgba(176, 107, 255, 0.6);
  }
  html[data-theme] .mini-player { left: 292px; }
}
html[data-theme] .dock .playbtn {
  border-radius: 50%; color: #0a0618;
  background: linear-gradient(150deg, #ffffff, #cfd8ff 34%, #b06bff 72%, #6fe4ff);
  box-shadow: 0 0 22px rgba(176, 107, 255, 0.55);
}
html[data-theme] .mini-player { border: 1px solid rgba(176, 107, 255, 0.4); border-radius: 999px; background: rgba(12, 9, 26, 0.9); }

html[data-theme] .cue.active .word { color: #ffffff; background: rgba(176, 107, 255, 0.22); box-shadow: 0 0 12px rgba(176, 107, 255, 0.5); border-radius: 4px; }
html[data-theme] ::-webkit-scrollbar-thumb { background: rgba(176, 107, 255, 0.42); border-radius: 999px; }

/* ---------- 12. 壁纸模式：全屏字幕层 ---------- */
html[data-theme] .wallpaper { background: radial-gradient(120% 100% at 12% -8%, #1a0f38 0%, #0a0718 56%, #04030b 100%); color: #ece9ff; }
html[data-theme] .wp-bg { filter: blur(40px) saturate(180%) brightness(.44) contrast(1.1); opacity: .9; }
html[data-theme] .wp-shade { background: linear-gradient(90deg, rgba(4,3,11,.95) 0%, rgba(14,10,34,.85) 48%, rgba(8,6,22,.7) 76%, rgba(4,3,11,.94) 100%), radial-gradient(72% 64% at 86% 14%, rgba(176,107,255,.22), transparent 64%), radial-gradient(58% 48% at 14% 86%, rgba(111,228,255,.18), transparent 66%); }
html[data-theme] .wp-kicker { color: #6fe4ff; font-weight:700;letter-spacing:.3em;text-transform:uppercase; }
html[data-theme] .wp-title { color: #ece9ff; font-weight:700;letter-spacing:-.01em;text-transform:uppercase; }
html[data-theme] .wp-cue.past, html[data-theme] .wp-cue.future { color: rgba(165,163,196,.82); }
html[data-theme] .wp-cue.active::before { background: linear-gradient(180deg, #6fe4ff, #b06bff); box-shadow: 0 0 30px rgba(176,107,255,.6); width:clamp(4px,.3vw,5px);border-radius:3px; }
html[data-theme] .wp-cue.active .wp-en { color: #ffffff; text-shadow: 0 0 26px rgba(176,107,255,.45); font-weight:700; }
html[data-theme] .wp-word.past { color: #ffffff; }
html[data-theme] .wp-word.active { color: rgba(255,255,255,.96); background-image: linear-gradient(180deg, transparent 60%, rgba(176,107,255,.42) 60%, rgba(111,228,255,.26) 94%, transparent 94%); text-shadow: 0 0 24px rgba(176,107,255,.5); border-radius:3px; }
html[data-theme] .wp-zh { color: rgba(165,163,196,.78); font-weight:400; }
html[data-theme] .wp-label { color: rgba(165,163,196,.5); }
html[data-theme] .wpbtn { background: linear-gradient(160deg, rgba(34,26,66,.78), rgba(10,8,24,.86)); border-color: rgba(176,107,255,.4); color: #ece9ff; border-radius:4px;letter-spacing:.14em;text-transform:uppercase;box-shadow:inset 0 1px 0 rgba(255,255,255,.28),0 18px 40px -22px rgba(176,107,255,.9); }
html[data-theme] .wpbtn:hover { background: rgba(176,107,255,.22); border-color: #6fe4ff; color: #ffffff; }
html[data-theme] .wp-shade::after { background: radial-gradient(58% 52% at 64% 56%, rgba(111,228,255,.14), transparent 72%); }

/* ---------- 13. 底栏几何：与内置对齐 ---------- */
html[data-theme] body .dock {
  left: 50% !important; right: auto !important; translate: -50% 0 !important; bottom: 16px !important;
  width: min(1040px, calc(100% - 40px)) !important; max-width: none !important; margin: 0 !important;
}
html[data-theme] body.player-open .dock {
  left: 0 !important; right: 0 !important; translate: none !important; bottom: 16px !important;
  width: auto !important; max-width: min(880px, calc(100vw - 40px)) !important; margin: 0 auto !important;
}
html[data-theme] .mini-player { left: 258px; right: 20px; }
@media (max-width: 1180px) { html[data-theme] .mini-player { left: 220px; } }
@media (max-width: 900px) { html[data-theme] .mini-player { left: 10px; right: 10px; bottom: 64px; } }
html[data-theme] body.nav-collapsed .mini-player { left: 20px; right: 20px; }

/* ---------- 14. 播放工具面板（更多）：按主题重绘 ---------- */

html[data-theme] .dshead h4 { color: var(--soft, var(--muted)); }
html[data-theme] .dstile { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--ink); border-radius: 12px; }
html[data-theme] .dstile svg { stroke: var(--muted); }
html[data-theme] .dstile:hover { background: var(--hover, var(--panel2)); border-color: var(--accent); color: var(--ink); }
html[data-theme] .dstile:hover svg { stroke: var(--accent); }
html[data-theme] .dstile[aria-pressed="true"], html[data-theme] .dstile[aria-expanded="true"] { border-color: var(--accent); }
html[data-theme] .dslabel { color: var(--muted); }
html[data-theme] .dspill, html[data-theme] .dsmute { background: var(--panel2, var(--panel)); border-color: var(--line); color: var(--soft, var(--ink)); }
html[data-theme] .dspill.on { color: var(--accent); border-color: var(--accent); }
html[data-theme] .dsrange { accent-color: var(--accent); }
html[data-theme] .iconbtn { background: var(--panel2, var(--panel)); border: 1px solid var(--line); color: var(--muted); }
